{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE `neshanka-wh.maplemonk.neshanka_google_sheet_Sales_Target_clean` AS SELECT SKU, date, CAST(REGEXP_REPLACE(sales_target_qty, r\'[,\s]\', \'\') AS INT64) as sales_target_qty, CAST(REGEXP_REPLACE(sales_target_value, r\'[,\s]\', \'\') AS INT64) as sales_target_value FROM `neshanka-wh.maplemonk.neshanka_google_sheet_Sales_Target`; CREATE OR REPLACE TABLE `neshanka-wh.maplemonk.shopify_product_performance_report` AS WITH sales_45_day AS ( SELECT SKU, SUM(quantity) as Sold_Quantity_45_Days FROM (select * from `neshanka-wh.maplemonk.NESHANKA_WH_sales_consolidated` where marketplace = \'WEBSITE\') WHERE DATE(order_Date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 45 DAY) GROUP BY sku ), sales_agg AS ( SELECT SKU, product_name_final as product_name, product_category as product_type, vendor, order_date, SUM(quantity) as total_quantity, SUM(selling_price) as total_line_value, safe_divide(SUM(selling_price),SUM(quantity) ) as sp FROM (select * from `neshanka-wh.maplemonk.NESHANKA_WH_sales_consolidated` where marketplace = \'WEBSITE\') o where ordeR_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 90 DAY) GROUP BY 1,2,3,4,5 ), daily_metrics AS ( SELECT SKU, SUM(CASE WHEN order_date = CURRENT_DATE() - 1 THEN total_quantity ELSE 0 END) as D_1_qty, SUM(CASE WHEN order_date = CURRENT_DATE() - 2 THEN total_quantity ELSE 0 END) as D_2_qty, SUM(CASE WHEN order_date = CURRENT_DATE() - 3 THEN total_quantity ELSE 0 END) as D_3_qty, ROUND(AVG(CASE WHEN order_date >= CURRENT_DATE() - 7 AND order_date < CURRENT_DATE() THEN total_quantity ELSE NULL END), 2) as W1_AVG_qty, ROUND(AVG(CASE WHEN order_date >= CURRENT_DATE() - 14 AND order_date < CURRENT_DATE() - 7 THEN total_quantity ELSE NULL END), 2) as W2_AVG_qty, ROUND(AVG(CASE WHEN order_date >= CURRENT_DATE() - 30 THEN total_quantity ELSE NULL END), 2) as M1_AVG_qty, ROUND(AVG(CASE WHEN order_date >= CURRENT_DATE() - 60 AND order_date < CURRENT_DATE() - 30 THEN total_quantity ELSE NULL END), 2) as M2_AVG_qty, SUM(CASE WHEN order_date >= DATE_TRUNC(CURRENT_DATE(), MONTH) THEN total_quantity ELSE 0 END) as MTD_qty, SUM(CASE WHEN order_date >= DATE_TRUNC(CURRENT_DATE(), MONTH) THEN total_line_value ELSE 0 END) as MTD_value FROM sales_agg GROUP BY SKU ) SELECT sa.SKU as RPC, sa.product_name, sr.Remarks, sr.Category, sr.Subcat as SubCategory, sr.Set, COALESCE(inv.available_inv_qty, 0) as Available_Inventory, COALESCE(inv.reserved_inv_qty, 0) as Reserved_Inventory, COALESCE(eo.open_orders_qty, 0) as Open_Orders_Easyecom, sa.sp as SP, dm.MTD_qty, st.sales_target_qty, dm.MTD_value, st.sales_target_value, ROUND(SAFE_DIVIDE(dm.MTD_qty, st.sales_target_qty), 2) as Percent_Achieved_Trending, ROUND(SAFE_DIVIDE(dm.MTD_value, st.sales_target_value), 2) as Percent_Achieved_Value, ROUND(dm.MTD_qty * 30 / EXTRACT(DAY FROM CURRENT_DATE()), 2) as Jan_Total_Qt_Extrapolated, ROUND(dm.MTD_value * 30 / EXTRACT(DAY FROM CURRENT_DATE()), 2) as Jan_Total_Value_Extrapolated, dm.D_1_qty, dm.D_2_qty, dm.D_3_qty, dm.W1_AVG_qty, dm.W2_AVG_qty, dm.M1_AVG_qty, dm.M2_AVG_qty FROM sales_agg sa LEFT JOIN daily_metrics dm ON sa.SKU = dm.SKU LEFT JOIN `neshanka-wh.maplemonk.neshanka_google_sheet_Set_and_remarks` sr ON LOWER(sa.SKU) = LOWER(sr.SKU) LEFT JOIN ( WITH latest_snapshot AS ( SELECT UPPER(REPLACE(REPLACE(SKU,\'\\'\',\'\'),\'`\',\'\')) AS sku_clean, MAX(_airbyte_normalized_at) AS latest_ts FROM `MapleMonk.easyecom_consolidated_inventory` GROUP BY sku_clean ) SELECT l.sku_clean AS SKU, SUM(CASE WHEN LOWER(e.status) = \'available\' THEN CAST(e.quantity AS INT64) ELSE 0 END) AS available_inv_qty, SUM(CASE WHEN LOWER(e.status) = \'reserved\' THEN CAST(e.quantity AS INT64) ELSE 0 END) AS reserved_inv_qty FROM `MapleMonk.easyecom_consolidated_inventory` e JOIN latest_snapshot l ON UPPER(REPLACE(REPLACE(e.SKU,\'\\'\',\'\'),\'`\',\'\')) = l.sku_clean AND e._airbyte_normalized_at = l.latest_ts GROUP BY l.sku_clean ) inv ON LOWER(sa.SKU) = LOWER(inv.SKU) LEFT JOIN sales_45_day sales_45 ON LOWER(sa.SKU) = LOWER(sales_45.SKU) LEFT JOIN ( SELECT SKU, sales_target_qty, sales_target_value FROM `neshanka-wh.maplemonk.neshanka_google_sheet_Sales_Target_clean` WHERE date LIKE \'2026-01%\' ) st ON LOWER(sa.SKU) = LOWER(st.SKU) LEFT JOIN ( SELECT UPPER(REPLACE(sku, \' \', \'\')) as sku_clean, SUM(CASE WHEN lower(order_status) = \'open\' THEN suborder_quantity ELSE 0 END) as open_orders_qty FROM `neshanka-wh.maplemonk.neshanka_wh_EasyEcom_FACT_ITEMS` GROUP BY UPPER(REPLACE(sku, \' \', \'\')) ) eo ON LOWER(sa.SKU) = eo.sku_clean WHERE sa.order_date = CURRENT_DATE() - 1 GROUP BY sa.SKU, sa.product_name, sr.Remarks, sr.Category, sr.Set, inv.available_inv_qty, inv.reserved_inv_qty, sa.sp, dm.MTD_qty, st.sales_target_qty, dm.MTD_value, st.sales_target_value, dm.D_1_qty, dm.D_2_qty, dm.D_3_qty, dm.W1_AVG_qty, dm.W2_AVG_qty, dm.M1_AVG_qty, dm.M2_AVG_qty, eo.open_orders_qty, sr.Subcat;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            